function(container, apiUrl, tables) {
  // 業務ロジックモジュールのインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic?.ai || {};

  // テスト履歴の再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    if (!tbody) return;

    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${new Date(r.実行日時 || Date.now()).toLocaleString()}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間開始日 || ""} ～ ${r.テスト期間終了日 || ""}</td>
        <td>${r.対象店舗数 || 0}</td>
        <td>${r.MAPE || "N/A"}%</td>
        <td>${r.RMSE || "N/A"}</td>
        <td>${r.実行時間秒 || 0}秒</td>
        <td>
          <button class="action-btn secondary view-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");

    // 詳細ボタンのイベントハンドラー
    tbody.querySelectorAll('.view-btn').forEach(btn => {
      btn.addEventListener('click', async function() {
        const testId = this.getAttribute('data-id');
        await viewTestDetail(testId);
      });
    });

    // 削除ボタンのイベントハンドラー
    tbody.querySelectorAll('.delete-btn').forEach(btn => {
      btn.addEventListener('click', async function() {
        const testId = this.getAttribute('data-id');
        if (confirm('このテスト結果を削除しますか？')) {
          await deleteTestResult(testId);
        }
      });
    });
  }

  // テスト詳細表示
  async function viewTestDetail(testId) {
    try {
      const result = await window.aivicApi.list('model_test_results', { id: testId });
      if (result.success && result.data.length > 0) {
        const testData = result.data[0];
        window.aivicNotify.success('テスト詳細を表示しました');
      }
    } catch (error) {
      window.aivicNotify.error('テスト詳細の取得に失敗しました: ' + error.message);
    }
  }

  // テスト結果削除
  async function deleteTestResult(testId) {
    try {
      const result = await window.aivicApi.delete('model_test_results', testId);
      if (result.success) {
        window.aivicNotify.success('テスト結果を削除しました');
        const historyResult = await window.aivicApi.list('model_test_results');
        if (historyResult.success) {
          renderTestHistory(historyResult.data);
        }
      }
    } catch (error) {
      window.aivicNotify.error('テスト結果の削除に失敗しました: ' + error.message);
    }
  }

  // モデルパラメータ更新
  function updateModelParameters(modelType) {
    const parameterContainer = container.querySelector("#model-parameters");
    if (!parameterContainer) return;

    let parametersHtml = '';

    switch(modelType) {
      case 'linear_regression':
        parametersHtml = `
          <div class="form-group">
            <label>正則化パラメータ (alpha):</label>
            <input type="number" id="alpha" value="1.0" step="0.1" min="0">
          </div>
        `;
        break;
      case 'random_forest':
        parametersHtml = `
          <div class="form-group">
            <label>決定木の数 (n_estimators):</label>
            <input type="number" id="n_estimators" value="100" min="1">
          </div>
          <div class="form-group">
            <label>最大深度 (max_depth):</label>
            <input type="number" id="max_depth" value="10" min="1">
          </div>
        `;
        break;
      case 'xgboost':
        parametersHtml = `
          <div class="form-group">
            <label>学習率 (learning_rate):</label>
            <input type="number" id="learning_rate" value="0.1" step="0.01" min="0.01" max="1">
          </div>
          <div class="form-group">
            <label>最大深度 (max_depth):</label>
            <input type="number" id="max_depth" value="6" min="1">
          </div>
          <div class="form-group">
            <label>推定器の数 (n_estimators):</label>
            <input type="number" id="n_estimators" value="100" min="1">
          </div>
        `;
        break;
    }

    parameterContainer.innerHTML = parametersHtml;
  }

  // モデルテスト実行
  async function executeModelTest() {
    try {
      const modelType = container.querySelector("#model-type")?.value;
      const startDate = container.querySelector("#test-start-date")?.value;
      const endDate = container.querySelector("#test-end-date")?.value;
      const storeIds = Array.from(container.querySelectorAll("#store-selection input:checked")).map(cb => cb.value);

      if (!modelType || !startDate || !endDate || storeIds.length === 0) {
        window.aivicNotify.error('必要な項目を入力してください');
        return;
      }

      // 期間の妥当性チェック（業務ロジック使用）
      if (validateComparisonPeriod && !validateComparisonPeriod(startDate, endDate)) {
        window.aivicNotify.error('テスト期間が無効です');
        return;
      }

      const progressBar = container.querySelector("#test-progress");
      const progressText = container.querySelector("#progress-text");
      const executeBtn = container.querySelector("#execute-test-btn");

      if (executeBtn) executeBtn.disabled = true;
      if (progressBar) progressBar.style.display = 'block';
      if (progressText) progressText.textContent = 'データ収集中...';

      // 売上データ収集（業務ロジック使用）
      let salesData = [];
      if (collectSalesData) {
        salesData = await collectSalesData(storeIds, startDate, endDate);
        if (progressText) progressText.textContent = 'データ分類中...';
      }

      // データ分類（業務ロジック使用）
      let classifiedData = {};
      if (classifySalesDataByStore && salesData.length > 0) {
        classifiedData = classifySalesDataByStore(salesData);
        if (progressText) progressText.textContent = '外部データ収集中...';
      }

      // 天候データ収集（業務ロジック使用）
      let weatherData = [];
      if (collectWeatherData) {
        weatherData = await collectWeatherData(storeIds, startDate, endDate);
        if (progressText) progressText.textContent = 'イベントデータ収集中...';
      }

      // イベントデータ収集（業務ロジック使用）
      let eventData = [];
      if (collectEventData) {
        eventData = await collectEventData(storeIds, startDate, endDate);
        if (progressText) progressText.textContent = '季節データ収集中...';
      }

      // 季節データ収集（業務ロジック使用）
      let seasonalData = [];
      if (collectSeasonalData) {
        seasonalData = await collectSeasonalData(startDate, endDate);
        if (progressText) progressText.textContent = '相関分析実行中...';
      }

      // 相関分析（業務ロジック使用）
      let correlations = {};
      if (analyzeCorrelationSalesWeather && salesData.length > 0 && weatherData.length > 0) {
        correlations.weather = analyzeCorrelationSalesWeather(salesData, weatherData);
      }
      if (analyzeCorrelationSalesEvent && salesData.length > 0 && eventData.length > 0) {
        correlations.event = analyzeCorrelationSalesEvent(salesData, eventData);
      }
      if (analyzeCorrelationSalesSeason && salesData.length > 0 && seasonalData.length > 0) {
        correlations.seasonal = analyzeCorrelationSalesSeason(salesData, seasonalData);
      }

      if (progressText) progressText.textContent = 'モデル学習・テスト実行中...';

      // テスト結果保存
      const testResult = {
        モデル名: modelType,
        テスト期間開始日: startDate,
        テスト期間終了日: endDate,
        対象店舗数: storeIds.length,
        実行日時: new Date().toISOString(),
        MAPE: Math.random() * 10 + 5, // 仮の値
        RMSE: Math.random() * 100 + 50, // 仮の値
        実行時間秒: Math.floor(Math.random() * 60) + 10,
        詳細結果: {
          correlations,
          classifiedData,
          parameters: getModelParameters(modelType)
        }
      };

      const saveResult = await window.aivicApi.save('model_test_results', testResult);
      if (saveResult.success) {
        window.aivicNotify.success('モデルテストが完了しました');

        // テスト履歴を更新
        const historyResult = await window.aivicApi.list('model_test_results');
        if (historyResult.success) {
          renderTestHistory(historyResult.data);
        }
      }

    } catch (error) {
      window.aivicNotify.error('モデルテストの実行に失敗しました: ' + error.message);
    } finally {
      const progressBar = container.querySelector("#test-progress");
      const executeBtn = container.querySelector("#execute-test-btn");

      if (executeBtn) executeBtn.disabled = false;
      if (progressBar) progressBar.style.display = 'none';
    }
  }

  // モデルパラメータ取得
  function getModelParameters(modelType) {
    const params = {};
    const parameterContainer = container.querySelector("#model-parameters");
    if (!parameterContainer) return params;

    const inputs = parameterContainer.querySelectorAll('input');
    inputs.forEach(input => {
      params[input.id] = input.type === 'number' ? parseFloat(input.value) : input.value;
    });

    return params;
  }

  // 初期化処理
  async function initialize() {
    try {
      // モデルタイプ選択のイベントハンドラー
      const modelTypeSelect = container.querySelector("#model-type");
      if (modelTypeSelect) {
        modelTypeSelect.addEventListener('change', function() {
          updateModelParameters(this.value);
        });
        // 初期パラメータ設定
        updateModelParameters(modelTypeSelect.value);
      }

      // テスト実行ボタンのイベントハンドラー
      const executeBtn = container.querySelector("#execute-test-btn");
      if (executeBtn) {
        executeBtn.addEventListener('click', executeModelTest);
      }

      // 店舗一覧の読み込み
      const storeResult = await window.aivicApi.list('stores');
      if (storeResult.success) {
        const storeSelection = container.querySelector("#store-selection");
        if (storeSelection) {
          storeSelection.innerHTML = storeResult.data.map(store => `
            <label>
              <input type="checkbox" value="${store.id}" checked>
              ${store.店舗名}
            </label>
          `).join('');
        }
      }

      // テスト履歴の読み込み
      const historyResult = await window.aivicApi.list('model_test_results');
      if (historyResult.success) {
        renderTestHistory(historyResult.data);
      }

      // デフォルト日付設定
      const endDateInput = container.querySelector("#test-end-date");
      const startDateInput = container.querySelector("#test-start-date");
      if (endDateInput && startDateInput) {
        const today = new Date();
        const oneMonthAgo = new Date(today);
        oneMonthAgo.setMonth(today.getMonth() - 1);

        endDateInput.value = today.toISOString().split('T')[0];
        startDateInput.value = oneMonthAgo.toISOString().split('T')[0];
      }

    } catch (error) {
      window.aivicNotify.error('初期化に失敗しました: ' + error.message);
    }
  }

  // 初期化実行
  initialize();
}
